-- VibeCritic manually authored editorial reference library. These are analytical methods, not claims about individual works.
CREATE TABLE IF NOT EXISTS editorial_reference_articles (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  work_type TEXT NOT NULL CHECK (work_type IN ('all','movie','tv','game')),
  topic TEXT NOT NULL,
  priority INTEGER NOT NULL DEFAULT 50,
  summary TEXT NOT NULL,
  prompt_excerpt TEXT NOT NULL,
  body TEXT NOT NULL,
  authoring TEXT NOT NULL DEFAULT 'VibeCritic editorial framework',
  version INTEGER NOT NULL DEFAULT 1,
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_editorial_reference_select ON editorial_reference_articles(active, work_type, priority DESC);
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body) VALUES ('evidence-before-opinion','من المعلومة إلى الحجة: كيف يُبنى الحكم النقدي','all','method',100,'الحكم النقدي ليس انطباعاً مزخرفاً؛ إنه نتيجة تربط معلومة قابلة للتحقق بتفسير واضح وأثر ملموس على التجربة. افصل دائماً بين ما نعرفه وما نستنتجه وما لا نملك دليلاً عليه.','ابنِ كل حكم من ثلاث حلقات: حقيقة محددة، تفسير يشرح دلالتها، وأثر على تجربة المتلقي. سمِّ حدود الدليل، ولا تحوّل غياب المعلومات إلى عيب أو فضيلة.','تبدأ المراجعة الجيدة من سؤال بسيط: ما الذي نعرفه فعلاً عن العمل، وما الذي نريد تفسيره؟ المعلومات المصدرية مثل أسماء الطاقم، مدة الفيلم، عدد الحلقات، المنصات أو تاريخ الإصدار حقائق قابلة للتحقق، لكنها لا تصنع حكماً نقدياً وحدها. اسم المخرج لا يثبت جودة الإخراج، ووجود ممثل موهوب لا يثبت نجاح الأداء، وارتفاع التقييم الجماهيري لا يثبت القيمة الفنية.\n\nالحجة النقدية تتكون من ثلاث حلقات مترابطة. أولاً: تفصيل محدد يمكن الإشارة إليه في المادة المتاحة. ثانياً: تفسير يشرح وظيفة هذا التفصيل داخل بنية العمل. ثالثاً: أثر يوضح لماذا يهم ذلك للمشاهد أو اللاعب. إذا غابت الحلقة الأولى صار الكلام تعميماً؛ وإذا غابت الثانية صار سرداً للمعلومات؛ وإذا غابت الثالثة صار تحليلاً بارداً لا يشرح قيمة القرار.\n\nيجب أيضاً تصنيف العبارات بحسب قوتها: حقيقة موثقة، ملاحظة من مصدر، استنتاج محدود، أو سؤال مفتوح. لا ترفع الاستنتاج إلى مرتبة الحقيقة، ولا تنسب إلى العمل مشهداً أو آلية لم يثبت وجودها. عندما تكون البيانات ناقصة، اذكر النقص وحدد ما يمنع الحكم، ثم انتقل إلى الجانب الذي تسمح الأدلة بتحليله. الصراحة بشأن حدود المعرفة علامة قوة تحريرية، لا اعتذار.') ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body) VALUES ('score-without-hype','الدرجة ليست شعبية: معايرة التقييم النقدي','all','scoring',95,'الدرجة تلخص الحجة ولا تستبدلها. افصل بين شعبية العمل وسمعته وبين جودة عناصره، وعاير كل محور مستقلاً وفق أثره وأدلته وحدود البيانات.','لا تستنتج الجودة من التقييم الجماهيري أو حجم الاهتمام. قيّم كل محور مستقلاً، واجعل الدرجة نتيجة لما شرحته المراجعة لا رقماً يسبقها.','تبدو الدرجة الرقمية دقيقة، لكنها قد تخفي حكماً مرتجلاً إذا لم تكن مرتبطة بمنهج ثابت. ينبغي أن تكون الدرجة خلاصة التحليل لا نقطة انطلاقه. يبدأ التقييم بتحديد المحاور التي يمكن الحكم عليها، ثم جمع الأدلة المتاحة لكل محور، ثم تفسير أثر القرارات الفنية، وبعد ذلك فقط تُمنح الدرجة.\n\nلا يجوز أن تنتقل شعبية العمل أو كثرة الأصوات أو ترتيب الترند إلى خانة الجودة. هذه مؤشرات على حجم الاهتمام أو الانطباع الجماهيري، وليست قياساً للسيناريو أو الإخراج أو الصوت أو الإيقاع. كما لا ينبغي أن تتساوى المحاور تلقائياً؛ فقد يكون العمل قوياً بصرياً ومحدوداً سردياً، أو مبتكراً في أنظمته لكنه غير مستقر تقنياً.\n\nالمعايرة الجيدة تستخدم معنى ثابتاً لكل نطاق: الدرجة المنخفضة تشير إلى خلل جوهري متكرر، والمتوسطة إلى نجاح جزئي مع قيود واضحة، والمرتفعة إلى تنفيذ متماسك ومميز تدعمه أمثلة. لا تمنح رقماً مرتفعاً لمجرد غياب معلومات سلبية، ولا تخفض الدرجة لأن بيانات جانب ما غير متاحة. إذا لم تسمح الأدلة بالحكم على محور، فاعترف بذلك بدلاً من اختراع يقين. يجب أن يستطيع القارئ العودة من الرقم إلى الفقرات التي تبرره.') ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body) VALUES ('screenplay-causality','السيناريو: السببية والاختيار وثمن القرار','movie','story',90,'لا تختزل السيناريو في الفكرة أو المفاجأة. اختبر علاقة السبب بالنتيجة، وفاعلية الشخصيات، وتطور الصراع، وما إذا كانت القرارات تترك أثراً حقيقياً.','حلّل سلسلة السبب والنتيجة: ماذا يريد البطل؟ ما الذي يمنعه؟ ما القرار الذي يغيّر المسار؟ وهل يدفع القرار ثمناً درامياً؟ لا تخلط كثرة الأحداث بتماسك البناء.','الفكرة الجذابة لا تكفي لصناعة سيناريو متماسك. الاختبار الأهم هو ما إذا كانت الأحداث تنشأ من اختيارات الشخصيات والضغوط التي تواجهها، أم أنها تتوالى لأن النص يحتاج إلى الوصول إلى مشهد بعينه. تتضح السببية حين يؤدي قرار إلى نتيجة، ثم تفرض النتيجة قراراً جديداً، فتتغير علاقة الشخصية بالعالم أو بالآخرين.\n\nاسأل عن رغبة الشخصية، والعائق الذي يمنعها، والثمن الذي تقبله أو ترفض دفعه. الشخصية الفاعلة لا تكتفي بتلقي الأحداث؛ إنها تتخذ قرارات تكشف قيمها وحدودها. أما التحول الدرامي فلا يقاس بعدد الصدمات أو الاعترافات، بل بمدى تغير السلوك أو الفهم بعد التجربة.\n\nيمكن للمفاجأة أن تعيد تفسير ما سبق، لكنها تصبح حيلة إذا اعتمدت على إخفاء معلومة كان ينبغي أن يعرفها المنظور السردي أو على مصادفة تحل الصراع. كما أن كثرة الخطوط لا تعني عمقاً؛ المهم أن تتقاطع الخطوط وتؤثر بعضها في بعض. قيّم النهاية بقدر ما تفي بالأسئلة التي زرعها العمل، لا بقدر صدمتها وحدها. ولا تحرق الأحداث عند شرح بنية الحجة؛ يكفي وصف وظيفة القرار دون كشف تفاصيله.') ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body) VALUES ('visual-direction','الإخراج واللغة البصرية: الصورة بوصفها قراراً','movie','visual',85,'الإخراج ليس قائمة لقطات جميلة. حلّل كيف تنظم الصورة انتباه المشاهد، وتحدد المسافة من الشخصيات، وتبني المكان والإيقاع والمعنى.','اربط اختيار الكادر والحركة والضوء والمونتاج بوظيفتها: أين يذهب انتباه المشاهد؟ ما الذي تخفيه الصورة أو تكشفه؟ وهل يتغير الأسلوب عندما يتغير الصراع؟','تتحول الصورة إلى لغة حين لا تكون مجرد زينة. الكادر يقرر ما يدخل مجال الرؤية وما يبقى خارجه، وحركة الكاميرا تنظم علاقتنا بالمكان والشخصية، والضوء واللون يحددان المزاج أو يخلقان تناقضاً مقصوداً. لكن لا يكفي وصف لقطة بأنها جميلة أو مظلمة أو واسعة؛ يجب شرح ما الذي تفعله داخل المشهد.\n\nاسأل: هل يوجه التكوين عين المشاهد إلى عنصر له وظيفة؟ هل تكشف المسافة البصرية عزلة الشخصية أو قربها؟ هل يتحول المكان مع تطور الصراع؟ وهل يضيف المونتاج توتراً أو وضوحاً أم يربك العلاقة بين الأحداث؟ الإيقاع البصري ليس سرعة القطع وحدها؛ قد تكون اللقطة الطويلة مشحونة إذا تغيرت داخلها علاقات القوة أو المعرفة.\n\nلا تنسب نية رمزية للمخرج بلا قرينة. يمكن قراءة التكرار أو التباين بوصفه احتمالاً عندما تدعمه أمثلة متكررة، لكن لا تحوّل كل لون إلى رمز ثابت. كما لا يمكن الحكم على جودة التصوير من اسم مدير التصوير أو ميزانية الإنتاج. الحكم الأقوى يربط اختياراً بصرياً محدداً بأثره على الفهم أو الشعور أو بنية السرد.') ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body) VALUES ('performance-and-character','الأداء والشخصيات: ما وراء الأسماء والنجومية','movie','performance',80,'وجود الممثل في الطاقم لا يثبت جودة الأداء. افحص اتساق الشخصية، ووضوح دوافعها، والتغير في السلوك، وما تسمح به الأدلة المتاحة عن الأداء.','لا تساوِ شهرة الممثل بعمق الشخصية. ميّز بين معلومات الطاقم وبين تحليل الأداء، ولا تدّع ملاحظة تعبير أو إلقاء أو كيمياء ما لم تتوفر مادة تثبتها.','تبدأ القراءة النقدية للشخصيات من الوظيفة الدرامية لا من شهرة الممثل. ما الذي تريده الشخصية؟ ما الذي تخشاه؟ ما التناقض الذي يجعل قراراتها قابلة للفهم حتى عندما تكون خاطئة؟ وهل تتغير بفعل الأحداث أم تبقى أداة لتحريك الحبكة؟ الشخصية المكتوبة جيداً لا تحتاج إلى أن تكون محبوبة؛ تحتاج إلى دوافع وقرارات وعواقب يمكن تتبعها.\n\nأما تحليل الأداء فيحتاج إلى شواهد من المادة نفسها: طريقة الإلقاء، التوقيت، الحركة، الصمت، التحول بين الحالات، أو التفاعل مع بقية الممثلين. لا يجوز استنتاج هذه العناصر من قائمة أسماء أو وصف تسويقي. إذا لم تتوفر مشاهدة مباشرة أو مصادر وصفية موثوقة، يمكن تحليل بنية الشخصيات المكتوبة مع التصريح بأن الحكم على الأداء التمثيلي محدود.\n\nالكيمياء بين الشخصيات ليست مجرد وجود ممثلين معروفين معاً؛ إنها إحساس بأن التفاعل يغير مسار العلاقة ويكشف شيئاً عن الطرفين. كذلك لا يعني طول الظهور أهمية الشخصية، ولا تعني قلة الحوار ضعفها. اربط كل ملاحظة بأثرها في الصراع، وتجنب اختراع مشاهد أو اقتباسات لتقوية الحجة.') ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body) VALUES ('series-time-architecture','المسلسل: هندسة الزمن وتطور الخطوط','tv','series',90,'قِس المسلسل بقدرته على تحويل الامتداد إلى تطور. عدد الحلقات لا يثبت الإيقاع؛ المهم تراكم القرارات وتحول العلاقات وتوازن الخطوط.','اسأل هل تغيّر كل حلقة حالة الصراع أو معرفة الشخصيات؟ هل تتقدم الخطوط بالتوازي أم تتكرر؟ لا تستنتج الحشو من عدد الحلقات وحده.','يمتلك المسلسل زمناً أوسع من الفيلم، لكن الامتداد لا يصبح قيمة تلقائياً. ينبغي أن تتحول الحلقات إلى مراحل في تطور الصراع والشخصيات، لا وحدات تكرر الحالة نفسها مع تأجيل الحل. يمكن للحلقة الهادئة أن تكون ضرورية إذا أعادت ترتيب العلاقات أو كشفت معلومة تغير فهمنا، كما يمكن لحلقة مليئة بالأحداث أن تكون ساكنة إذا لم تترك أثراً.\n\nاختبر العلاقة بين الخطوط السردية: هل يضيء أحدها الآخر؟ هل تؤثر القرارات في أكثر من شخصية؟ هل تتقدم الخطوط بسرعات مختلفة لخلق توتر، أم تتناوب بلا ضرورة؟ وفي نهاية الموسم، هل تتغير حالة العالم أو الشخصيات بما يبرر الرحلة؟ لا تقِس جودة البناء بعدد الحلقات أو المواسم، ولا تفترض أن كل نهاية مفتوحة عيب؛ اسأل هل الإغلاق الجزئي يفي بوعد الموسم ويمنح الاستمرار معنى.\n\nمدة الحلقة وعددها بيانات وصفية فقط. لا تثبت وحدها الحشو أو البطء أو العمق. إذا لم تتوفر معلومات تفصيلية عن الحلقات، لا تصف إيقاعها كما لو أنك شاهدتها؛ وضّح أن الحكم البنيوي محدود، واستند إلى ما هو متاح فقط.') ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body) VALUES ('gameplay-systems','اللعب: الأنظمة والاختيار والتغذية الراجعة','game','gameplay',95,'جوهر اللعب هو العلاقة بين فعل اللاعب واستجابة النظام. حلّل وضوح القواعد، وعمق الخيارات، وتنوع التحدي، ومدى تأثير القرارات لا مجرد قائمة الميزات.','اختبر منطق الفعل والاستجابة: ماذا يطلب النظام من اللاعب؟ ما الخيارات ذات المعنى؟ هل تتغير الاستراتيجية مع تقدم اللعب؟ لا تساوِ كثرة الأنظمة بعمقها.','لا يصف عدد الأسلحة أو المهارات أو أنماط اللعب جودة التجربة. السؤال المركزي هو ما العلاقة التي يبنيها النظام بين فعل اللاعب والنتيجة التي يراها. حين تكون القواعد مفهومة والتغذية الراجعة واضحة، يستطيع اللاعب التعلم والتجريب وربط قراراته بالعواقب. أما إذا أخفى النظام قواعده أو عاقب اللاعب بلا تفسير، يصبح التحدي ارتباكاً لا عمقاً.\n\nافحص الخيارات: هل يغير اختيار السلاح أو المسار أو القدرة طريقة التعامل مع الموقف، أم أنه اختلاف رقمي محدود؟ هل تتكامل الأنظمة أم تتنافس على انتباه اللاعب؟ وهل يضيف التقدم أدوات تفتح أساليب جديدة، أم يرفع الأرقام فقط؟ التنوع الحقيقي لا يعني كثرة الأنشطة، بل اختلاف القرارات التي تتطلبها.\n\nينبغي أيضاً التمييز بين ما هو معلن في وصف اللعبة وما ثبت في تجربة أو مراجعات موثوقة. لا تدّع اختبار الاستجابة أو التوازن أو صعوبة المراحل اعتماداً على صفحة متجر. إذا لم تتوفر مادة لعب مباشرة أو مصادر كافية، حلّل تصميم الأنظمة المعلن وحدد ما لا يمكن الحكم عليه بعد.') ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body) VALUES ('level-design-space','تصميم المراحل: المكان كأداة للتعلم والتوتر','game','level-design',85,'المرحلة الجيدة لا تُقاس بحجم الخريطة فقط. افحص كيف يعلّم المكان قواعده، ويوجه اللاعب، ويصنع اختيارات ومخاطر واكتشافات ذات معنى.','حلّل وظيفة المساحة: كيف يتعلم اللاعب الطريق؟ أين تظهر المخاطر والاختصارات؟ هل تكافئ الاستكشاف؟ وهل يخدم توزيع الموارد والخصوم إيقاع التحدي؟','المكان في اللعبة ليس خلفية محايدة؛ إنه جزء من النظام الذي يتعلمه اللاعب ويتفاعل معه. تصميم المرحلة يوجه الحركة عبر الممرات والرؤية والعوائق والإشارات البصرية، ويوازن بين ما يعرفه اللاعب وما يكتشفه. يمكن لمساحة صغيرة أن تكون غنية إذا قدمت خيارات ومسارات وتغيرات في فهم اللاعب، بينما قد تبدو خريطة واسعة فارغة إذا لم تمنح الحركة معنى.\n\nاسأل كيف تُعلّم المرحلة قواعدها من دون شرح زائد. هل يلاحظ اللاعب الخطر قبل أن يواجهه؟ هل توجد مسارات بديلة ذات تكلفة ومكافأة؟ هل يتغير استخدام المكان بعد اكتساب قدرة جديدة؟ وهل ينسجم توزيع الموارد والأعداء ونقاط الحفظ مع منحنى التوتر؟ الاستكشاف الناجح لا يعني إخفاء كل شيء، بل بناء فضول يمكن مكافأته.\n\nلا يمكن استنتاج جودة تصميم المراحل من صور ترويجية أو حجم الخريطة المعلن. يلزم وصف تفصيلي أو تحليل موثوق للمسارات واللقاءات. عند غياب ذلك، امتنع عن أحكام مثل عالم فارغ أو مراحل عبقرية، وقل بوضوح إن الأدلة المتاحة لا تكفي.') ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,version=excluded.version,active=1,updated_at=datetime('now');
INSERT INTO editorial_reference_articles (slug,title,work_type,topic,priority,summary,prompt_excerpt,body) VALUES ('technical-performance','الأداء التقني: الثبات جزء من التصميم','game','technical',80,'الأداء التقني ليس تفصيلاً منفصلاً عن اللعب. الإطارات والاستجابة والأعطال وأوقات التحميل تؤثر في الإحساس بالتحكم والإنصاف والاستمرارية.','اربط القياس التقني بأثره: هل يضر هبوط الإطارات بالتصويب أو التوقيت؟ هل تؤثر الأعطال في التقدم؟ لا تذكر أرقام أداء بلا جهاز واختبار ومصدر محدد.','لا يكفي وصف لعبة بأنها محسنة أو ثقيلة. ينبغي ربط المؤشرات التقنية بتجربة اللعب: هبوط الإطارات قد يضر التوقيت أو دقة التصويب، وتأخر الاستجابة قد يضعف الإحساس بالتحكم، وأوقات التحميل الطويلة قد تقطع تدفق الاستكشاف، بينما تؤثر الأعطال وفقدان الحفظ في الثقة بالنظام كله.\n\nأي رقم تقني يحتاج إلى سياق: المنصة، إعدادات الرسوم، نسخة اللعبة، موضع الاختبار، وأداة القياس أو المصدر. لا تقارن رقماً من جهاز قوي بآخر من جهاز مختلف، ولا تعمم تجربة نسخة الإطلاق على تحديثات لاحقة من دون تاريخ. كما أن الدقة الرسومية وحدها لا تعني جودة الأداء؛ قد تقدم اللعبة صورة جميلة مع تنازلات مؤثرة في الثبات أو الاستجابة.\n\nإذا لم تتوفر اختبارات مستقلة موثوقة، لا تخترع معدل إطارات أو تحكماً مثالياً أو مشكلات تقنية. يمكن ذكر أن البيانات التقنية غير كافية، مع شرح ما الذي ينبغي اختباره قبل إصدار حكم نهائي. النزاهة هنا أهم من ملء محور تقني بتخمينات.') ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,version=excluded.version,active=1,updated_at=datetime('now');
